with vals(fintech_id,business_model,target_customer,revenue_model,bm_conf,tc_conf,rev_conf,bm_basis,tc_basis,rev_basis,source_url) as (
 values
 ('ENT-RUT-59294680-7','B2B','EMPRESAS','INTERES_ORIGINACION',0.999::numeric,0.999::numeric,0.97::numeric,'Xepelin ofrece factoring, crédito, financiamiento directo y financiamiento de pagos a Pymes y empresas mediante una plataforma 100% digital.','La oferta vigente está dirigida explícitamente a empresas, desde Pymes hasta corporativos.','Los productos de crédito muestran tasa de interés y los productos de factoring descuentan comisión/costo de financiamiento; se clasifica como margen financiero/originación dentro de la taxonomía actual.','https://xepelin.com/credito-chile'),
 ('ENT-RUT-76400275-K','B2B2C','AMBOS','COMISION_TRANSACCIONAL',0.999::numeric,0.97::numeric,0.95::numeric,'RedCapital es una plataforma de financiamiento colectivo que conecta Pymes solicitantes con inversionistas.','La plataforma atiende empresas/Pymes que buscan financiamiento y una contraparte de inversionistas; se representa como ecosistema de dos lados.','La documentación vigente describe derechos/comisiones por participar en operaciones de inversión, por lo que la remuneración observable se modela como comisión por operación dentro de la taxonomía actual.','https://redcapital.cl/como-funciona-solicitar'),
 ('ENT-RUT-77073836-9','B2B2C','AMBOS',null,0.999::numeric,0.999::numeric,null,'Banca.me combina crédito/BNPL para personas con soluciones para comercios e inmobiliarias y software de evaluación/financiamiento.','La oferta vigente atiende personas que compran o financian vivienda y empresas/comercios que integran BNPL o financiamiento de pie.','La plataforma muestra simultáneamente intereses y comisión de servicio, y utiliza vehículos de crédito separados; no se fuerza un único modelo principal de ingresos.','https://www.banca.me/'),
 ('ENT-RUT-76865845-5','B2B','EMPRESAS',null,0.999::numeric,0.999::numeric,null,'Los términos de Simpli indican expresamente servicios financieros a empresas/personas jurídicas; la oferta actual incluye factoring, payments, ordering, confirming y dashboard empresarial.','El cliente observado es empresa/persona jurídica, principalmente Pymes y corporativas.','La oferta combina factoring y servicios de pagos; la evidencia actual no permite representar responsablemente toda la monetización con un único código existente.','https://simpli.cl/')
), logged as (
 select v.fintech_id,'MANUAL_OFFICIAL_LENDING_2026_09_09',v.business_model,v.bm_conf,v.target_customer,v.tc_conf,v.revenue_model,v.rev_conf,1,now(),jsonb_build_object('source_url',v.source_url,'business_model_basis',v.bm_basis,'target_customer_basis',v.tc_basis,'revenue_model_basis',v.rev_basis,'manual_validation',true,'cohort','LENDING_CORE') from vals v returning fintech_id
)
update public.aml_fintech_entity e
set business_model=v.business_model,target_customer=v.target_customer,revenue_model=v.revenue_model,business_model_basis=v.bm_basis,business_model_confidence=v.bm_conf,target_customer_basis=v.tc_basis,target_customer_confidence=v.tc_conf,revenue_model_basis=v.rev_basis,revenue_model_confidence=v.rev_conf,profile_classifier_version='MANUAL_OFFICIAL_LENDING_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
from vals v where e.fintech_id=v.fintech_id and exists(select 1 from logged l where l.fintech_id=e.fintech_id);

on conflict(fintech_id,rut,role_code) do update set atlas_entity_id=excluded.atlas_entity_id,legal_name=excluded.legal_name,is_primary=false,regulator=excluded.regulator,registry=excluded.registry,source_code=excluded.source_code,source_url=excluded.source_url,evidence_basis=excluded.evidence_basis,confidence=excluded.confidence,last_seen_at=now(),metadata=excluded.metadata;

on conflict(observation_key) do update set evidence_status=excluded.evidence_status,evidence_class=excluded.evidence_class,confidence=excluded.confidence,basis=excluded.basis,source_code=excluded.source_code,source_url=excluded.source_url,evidence_excerpt=excluded.evidence_excerpt,last_seen_at=now(),observed_at=excluded.observed_at;

on conflict(observation_key) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,qualifier=excluded.qualifier,evidence_type=excluded.evidence_type,confidence=excluded.confidence,source_url=excluded.source_url,observed_at=excluded.observed_at,basis=excluded.basis,evidence_excerpt=excluded.evidence_excerpt,metadata=excluded.metadata,last_seen_at=now();

select public.aml_fintech_refresh_functional_profile();